    public let rawValue: String
    public let format: String
    public let fields: [String]
    public let hasAmbiguousWeekday: Bool
    public let descriptionZh: String
    public let isValidFiveField: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(rawValue: String, format: String, fields: [String], hasAmbiguousWeekday: Bool, descriptionZh: String, isValidFiveField: Bool) {
        self.rawValue = rawValue
        self.format = format
        self.fields = fields
        self.hasAmbiguousWeekday = hasAmbiguousWeekday
        self.descriptionZh = descriptionZh
        self.isValidFiveField = isValidFiveField
    }
}

