extension CronSummaryFfi: Equatable, Hashable {
    public static func ==(lhs: CronSummaryFfi, rhs: CronSummaryFfi) -> Bool {
        if lhs.rawValue != rhs.rawValue {
            return false
        }
        if lhs.format != rhs.format {
            return false
        }
        if lhs.fields != rhs.fields {
            return false
        }
        if lhs.hasAmbiguousWeekday != rhs.hasAmbiguousWeekday {
            return false
        }
        if lhs.descriptionZh != rhs.descriptionZh {
            return false
        }
        if lhs.isValidFiveField != rhs.isValidFiveField {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(rawValue)
        hasher.combine(format)
        hasher.combine(fields)
        hasher.combine(hasAmbiguousWeekday)
        hasher.combine(descriptionZh)
        hasher.combine(isValidFiveField)
    }
