/**
 * FFI 统一错误类型。
 */
public enum CoreFfiError: Swift.Error {

    
    
    case InvalidAddress(msg: String
    )
    case InvalidEndpoint(msg: String
    )
    case InvalidJson(msg: String
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCoreFfiError: FfiConverterRustBuffer {
    typealias SwiftType = CoreFfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CoreFfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidAddress(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 2: return .InvalidEndpoint(
            msg: try FfiConverterString.read(from: &buf)
            )
        case 3: return .InvalidJson(
            msg: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CoreFfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidAddress(msg):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InvalidEndpoint(msg):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(msg, into: &buf)
            
        
        case let .InvalidJson(msg):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(msg, into: &buf)
            
        }
    }
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public func FfiConverterTypeCoreFfiError_lift(_ buf: RustBuffer) throws -> CoreFfiError {
    return try FfiConverterTypeCoreFfiError.lift(buf)
}

