fileprivate struct FfiConverterSequenceTypeSseEventFfi: FfiConverterRustBuffer {
    typealias SwiftType = [SseEventFfi]

    public static func write(_ value: [SseEventFfi], into buf: inout [UInt8]) {
        let len = Int32(value.count)
        writeInt(&buf, len)
        for item in value {
            FfiConverterTypeSseEventFfi.write(item, into: &buf)
        }
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> [SseEventFfi] {
        let len: Int32 = try readInt(&buf)
        var seq = [SseEventFfi]()
        seq.reserveCapacity(Int(len))
        for _ in 0 ..< len {
            seq.append(try FfiConverterTypeSseEventFfi.read(from: &buf))
        }
        return seq
    }
}
